import matplotlib.pyplot as plt
import pandas as pd
import pypowsybl as pp

network = pp.network.load("../data/ieee14/IEEE14.iidm")
network.get_generators()[["name", "target_p", "target_v", "max_p", "voltage_regulator_on"]]
```

